class Component extends DCLogic {
 constructor(p){super(p);this.state={status:'confirmed',cancelling:false,reschedule:false,checks:{},question:'',asked:false,error:false};}
 renderVals(){const s=this.state,items=[{id:'group',title:'Познакомиться с участниками группы',link:'Group.dc.html'},{id:'contact',title:'Сохранить контакт ведущей',link:'Messages.dc.html'},{id:'clothes',title:'Подготовить удобную одежду',link:''}];return {modes:[['pending','Нужно подтвердить'],['confirmed','Подтверждено'],['cancelled','Другая дата']].map(([id,title])=>({title,cls:s.status===id?'is-on':'',pick:()=>this.setState({status:id,cancelling:false,reschedule:false})})),heroLabel:s.status==='cancelled'?'Обсудим другой выход':'Твой первый выход',heroTitle:s.status==='cancelled'?'Планы изменились':'24 октября, 14:00',canConfirm:s.status==='pending',confirmed:s.status==='confirmed',cancelled:s.status==='cancelled',confirm:()=>this.setState({status:'confirmed'}),startCancel:()=>this.setState({cancelling:true}),cancelling:s.cancelling,cancel:()=>this.setState({status:'cancelled',cancelling:false}),keep:()=>this.setState({cancelling:false}),restore:()=>this.setState({reschedule:true}),reschedule:s.reschedule,checks:items.map(c=>({...c,hasLink:!!c.link,checked:!!s.checks[c.id],toggle:()=>this.setState({checks:{...this.state.checks,[c.id]:!this.state.checks[c.id]}})})),progress:Object.values(s.checks).filter(Boolean).length+' из 3',question:s.question,changeQuestion:e=>this.setState({question:e.target.value,asked:false,error:false}),ask:()=>this.setState(s.question.trim()?{asked:true,error:false}:{error:true}),asked:s.asked,hasError:s.error};}
}
